  const svgRetorno = SV(130, `<rect x="20" y="70" width="260" height="20" fill="var(--ice)" opacity=".35"/><path d="M40 60H260" stroke="var(--err)" stroke-width="4"/><path d="M40 60H260" stroke="#fff" stroke-width="2" class="a-flow" opacity=".7"/><path d="M260 80H40" stroke="var(--ice)" stroke-width="3" stroke-dasharray="6 4" class="a-flow-rev"/>${tx(150, 50, 'ida: pista', 'vizsm', mid)}${tx(150, 106, 'vuelta: plano de masa, justo debajo', 'vizsm', mid)}${tx(150, 124, 'Ida y vuelta juntas: bucle mínimo', 'vizlab', mid)}`);
  const svgBucle = SV(120, `<rect x="40" y="30" width="220" height="60" rx="4" fill="var(--err)" opacity=".2"/><path d="M40 30H260V90H40Z" stroke="var(--err)" stroke-width="3" fill="none"/>${[0, 1, 2].map(i => `<path d="M${270 + i * 8} ${44 - i * 3}q10 16 0 32" stroke="var(--err)" stroke-width="2" fill="none" class="a-pulse a-d${i + 1}"/>`).join('')}${tx(150, 66, 'área del bucle = antena', 'vizlab', mid)}${tx(150, 112, 'Más área → más emisiones y más ruido captado', 'vizsm', mid)}`);
  const svgCapas4 = SV(120, `${[['Señales', CU], ['Masa (entera)', '#4a7fc0'], ['Alimentación', '#c05a4a'], ['Señales', CU]].map(([n, c], i) => `<rect x="40" y="${16 + i * 24}" width="180" height="10" fill="${c}"/>${tx(228, 25 + i * 24, n, 'vizsm')}`).join('')}${tx(150, 116, 'Cuatro capas: un plano de masa bajo todas las señales', 'vizsm', mid)}`);
