  const svgMicro = SV(120, `<rect x="20" y="70" width="260" height="10" fill="#4a7fc0"/><rect x="20" y="58" width="260" height="12" fill="#c9b98a"/><rect x="130" y="50" width="40" height="8" fill="${CU}"/>${tx(150, 44, 'anchura', 'vizsm', mid)}${tx(286, 68, 'h', 'vizsm', end)}${tx(150, 100, 'Z₀ depende de la anchura, del grosor h y del material', 'vizsm', mid)}${tx(150, 116, 'RF: 50 Ω · USB: pares de 90 Ω', 'vizlab', mid)}`);
  const svgPar = SV(100, `<path d="M20 40H120q10 0 14 -6t14 0t14 6H280M20 56H280" stroke="${CU}" stroke-width="4" fill="none"/>${tx(150, 20, 'par diferencial: juntas y con la misma longitud', 'vizsm', mid)}${tx(141, 84, 'serpentina para igualar longitudes', 'vizsm', mid)}`);
